export function verifiedStaffRoles(name: string): StaffRole[] {
  const key = name.normalize("NFKD").replace(/[\u0300-\u036f]/g, "").replace(/[’'\x60]/g, "").replace(/[^a-z0-9]/gi, "").toLowerCase();
  return Array.from(new Set((verifiedRoleHistories[key]?.appointments ?? []).map((appointment) => appointment.role))) as StaffRole[];
}
